"""Triage helper: move reviewed entries to the archive queue."""

import json
from pathlib import Path

QUEUE = Path("tools/review_queue.json")


def load_queue(path=QUEUE):
    return json.loads(path.read_text())


def archive_reviewed(entries):
    pending = [e for e in entries if e.get("status") != "reviewed"]
    done = [e for e in entries if e.get("status") == "reviewed"]
    return pending, done


if __name__ == "__main__":
    pending, done = archive_reviewed(load_queue())
    print(f"{len(pending)} pending, {len(done)} reviewed")
